STD_FILE={k: k+'.pdf' for k in P}
PROC=re.compile(r'терапи|лазер|\bУФ|UVB|UVA|УФО|ПУВА|PUVA|облучен|НИЛИ|плазмаферез|озон|PRP|микронидлинг|дарсонвал|фонофорез|электро|бальнео|пелоид|крио|трансплант|FUT|FUE|DHI|ARTAS|процедур|(?<![а-яё])ванн|LLLT|поляризованный полихроматический луч|ограничени|ультразвук|фотодинам|кюретаж|иссечен|коагуляц|аппарат|магнит|массаж|SVF|клеточн|экзосом|факторов роста|факторы роста|диатерм|гипербар|ИК-|светолеч|ионофорез|грязе|хирург|удален|деструкц|эксимер|аутологичн|гемосорбц|радиоволн|шейвинг|дерматоскоп',re.I)
DIET=re.compile(r'^(стол|диет|гипоаллерг|режим)',re.I)
TOP=re.compile(r'наружн|нанос|наносят|аппликац|втира|смазыв|\bмазь|\bкрем|\bгель|лосьон|шампун|примочк|пластыр|\bлак\b|спрей|аэрозол|на очаг|местно|интрафокальн|внутриочаг|внутрикожн|на поражен|на кожу|компресс|пудр|паст[аы]\b|капли глазн|полоскан|ванночк|влагалищ|вагинал|суппозитори.*вагин',re.I)
SYS=re.compile(r'в/в|в/м|п/к|внутрь|перорал|per os|таблет|капсул|инъекц|внутривен|внутримыш|подкож|капельн|драже|сироп|ректальн|мг/кг|мг/сут|сублингв|рассасыв',re.I)
def classify(name,dose):
    if PROC.search(name): return 'procedure'
    t=dose[:160]
    tn=TOP.search(name+' '+t); sn=SYS.search(name+' '+t)
    if tn and not sn: return 'topical'
    if sn and not tn: return 'systemic'
    if tn and sn:
        a=TOP.search(t); b=SYS.search(t)
        if a and b: return 'topical' if a.start()<b.start() else 'systemic'
        return 'topical' if TOP.search(name) else 'systemic'
    return 'topical' if '%' in name else 'systemic'
JUNK=re.compile(r'\s*(Вид\s?ы и ст|По\s?уровню и|П\s?о уровню|Примечание|симости о\s?т|непатентованное\)|средства \(междунар|Лекарственных средств|применения препарата больница|больница учреждения).*$',re.S)
SHORTOK=re.compile(r'^(\d+|в|и|с|к|о|у|по|до|на|не|за|от|из|мг|мл|г|%|—|-|–|раз|•|\+|х|в/в|в/м|п/к|МЕ|ЕД|нм|см|кг|сут|см2|1%|2%|5%)$')
def garb(t):
    w=t.split()
    if len(w)<5: return False
    return sum(1 for x in w if len(x)<=2 and not SHORTOK.match(x))/len(w)>0.16
def clean(s): 
    s=re.sub(r'\s+',' ',s).strip(' ;,')
    s=s.replace('– х','–х').replace(' – х','–х')
    return s
out=[];allnames=set()
for nid,title,icd,kp,kpp,stdk,extra in N:
    s=P[stdk]
    drugs=[];seen=set()
    for d in s['drugs']:
        name=clean(JUNK.sub('',d['name'])); dose=clean(JUNK.sub('',d['dose']))
        if re.search('[қўҳғ]',dose): dose=''
        name=re.sub(r'^([А-ЯЁ]{3,})[a-zа-яё]$',r'\1',name)
        if re.match(r'^[А-ЯЁ][а-яё]{1,3}$',name) and re.match(r'^[а-яё]',dose):
            w=dose.split(' ',1); name=name+w[0]; dose=w[1] if len(w)>1 else ''
        if (re.match(r'^[-–•]\s|^-[А-ЯЁа-яё]',name) or (re.match(r'^[а-яё]',name) and not dose and ' ' in name)) and drugs:
            p=drugs[-1]; p['d']=clean(p['d']+' '+name+' '+dose)
            if d['daily']: p['dd']=clean(p['dd']+'; '+clean(d['daily']))
            if d['course']: p['cd']=clean(p['cd']+'; '+clean(d['course']))
            continue
        if DIET.match(name) or len(name)<3 or name.lower().startswith(('интубация','примечание')): continue
        if garb(name) and (len(name)>40 or not dose): continue
        bad=garb(dose)
        key=(name.lower(),dose.lower())
        if key in seen: continue
        seen.add(key)
        daily=clean(d['daily']); course=clean(d['course'])
        if daily==dose: daily=''
        if course==dose: course=''
        if bad: dose=''
        if garb(daily): daily=''
        if garb(course): course=''
        e=dict(g=classify(name,dose),s='a' if d['sub']=='дополнительные' else 'm',n=name,d=dose,dd=daily,cd=course,sp=not d['amb'],p=d['page'])
        if bad: e['bad']=1
        drugs.append(e)
    diags=[];seen=set()
    for d in s['diag']:
        nm=clean(d['name'])
        if nm.lower() in seen: continue
        seen.add(nm.lower())
        diags.append(dict(c=clean(d['cat'] or ''),n=nm,sp=not d['amb']))
    pages=[d['page'] for d in s['drugs']]
    out.append(dict(id=nid,title=title,icd=[dict(code=c,name=n) for c,n in icd],kp=dict(file=kp,page=kpp),std=dict(file=STD_FILE[stdk],page=min(pages) if pages else 1),extra=[dict(file=f,title=t) for f,t in extra],diag=diags,drugs=drugs))
